WITH p AS (SELECT coalesce(%s::text,'') ip,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.ip,a.line_code,b.version,b.date0,b.time0,b.user_id0,b.date2,b.time2,b.user_id2,count(*) OVER() total FROM public.mflist_line_station a JOIN public.mflist_line l ON l.line_code=a.line_code AND l.status='1' LEFT JOIN public.mes_oi_version b ON b.ip=a.ip CROSS JOIN s WHERE s.ok IS NOT NULL AND a.ip<>'' AND(s.ip='' OR a.ip=ANY(string_to_array(s.ip,','))) AND (s.unrestricted OR l.branch_code=ANY(string_to_array(s.bs,','))) ORDER BY a.line_code,a.ip LIMIT(SELECT lim FROM p);
